// Extraer datos del mensaje de WhatsApp
const entry = $input.first().json.body.entry[0];
const changes = entry.changes[0];
const value = changes.value;
const message = value.messages[0];
const contact = value.contacts ? value.contacts[0] : {};

const phoneNumberId = value.metadata.phone_number_id;
const from = message.from; // número del cliente
const msgType = message.type; // text, audio, image, etc.
const timestamp = message.timestamp;
const clientName = contact.profile ? contact.profile.name : 'Cliente';
const messageId = message.id;

let userMessage = '';
let mediaId = null;

if (msgType === 'text') {
  userMessage = message.text.body;
} else if (msgType === 'audio') {
  mediaId = message.audio.id;
  userMessage = '__AUDIO__';
} else if (msgType === 'image') {
  userMessage = message.image.caption || 'El cliente envió una imagen';
} else if (msgType === 'interactive') {
  if (message.interactive.type === 'button_reply') {
    userMessage = message.interactive.button_reply.title;
  } else if (message.interactive.type === 'list_reply') {
    userMessage = message.interactive.list_reply.title;
  }
} else {
  userMessage = `El cliente envió un mensaje de tipo: ${msgType}`;
}

return [{
  json: {
    phoneNumberId: phoneNumberId,
    from: from,
    clientName: clientName,
    messageType: msgType,
    userMessage: userMessage,
    mediaId: mediaId,
    messageId: messageId,
    sessionId: `whatsapp_${from}`,
    timestamp: timestamp
  }
}];

// Preparar texto transcrito del audio para el agente
const transcription = $input.first().json.text || 'No pude entender el audio';

// Recuperar datos originales del mensaje
const originalData = $('Extraer Datos WhatsApp').first().json;

return [{
  json: {
    phoneNumberId: originalData.phoneNumberId,
    from: originalData.from,
    clientName: originalData.clientName,
    userMessage: transcription,
    messageType: 'audio_transcribed',
    sessionId: originalData.sessionId
  }
}];

const staticData = $getWorkflowStaticData('global');

if (!staticData.citas) {
  staticData.citas = [];
}

const queryStr = $input.first().json.query || '{}';
let citaData;
try {
  citaData = JSON.parse(queryStr);
} catch(e) {
  citaData = { raw: queryStr };
}

const nuevaCita = {
  id: `CITA-${Date.now()}`,
  cliente: citaData.cliente || citaData.nombre || 'Sin nombre',
  servicio: citaData.servicio || 'Sin especificar',
  barbero: citaData.barbero || 'Sin preferencia',
  fecha: citaData.fecha || 'Sin especificar',
  hora: citaData.hora || 'Sin especificar',
  telefono: citaData.telefono || 'Sin especificar',
  precio: citaData.precio || 'Sin especificar',
  estado: 'confirmada',
  creadaEn: new Date().toISOString()
};

staticData.citas.push(nuevaCita);

return `Cita guardada exitosamente con ID: ${nuevaCita.id}. Cliente: ${nuevaCita.cliente}, Servicio: ${nuevaCita.servicio}, Barbero: ${nuevaCita.barbero}, Fecha: ${nuevaCita.fecha}, Hora: ${nuevaCita.hora}.`;

const staticData = $getWorkflowStaticData('global');
const citas = staticData.citas || [];
const queryStr = $input.first().json.query || '';

const citasActivas = citas.filter(c => c.estado === 'confirmada');

if (citasActivas.length === 0) {
  return 'No hay citas registradas. Todos los horarios estan disponibles.';
}

let resultado = citasActivas;
if (queryStr) {
  resultado = citasActivas.filter(c => {
    const query = queryStr.toLowerCase();
    return (c.fecha && c.fecha.toLowerCase().includes(query)) ||
           (c.barbero && c.barbero.toLowerCase().includes(query)) ||
           (c.cliente && c.cliente.toLowerCase().includes(query));
  });
}

if (resultado.length === 0) {
  return `No se encontraron citas para "${queryStr}". Todos los horarios estan disponibles.`;
}

const horariosOcupados = resultado.map(c => 
  `- ${c.fecha} a las ${c.hora}: ${c.cliente} con ${c.barbero} (${c.servicio})`
).join('\n');

const horariosBase = ['8:00', '8:45', '9:30', '10:15', '11:00', '11:45', '12:30', '13:15', '14:00', '14:45', '15:30', '16:15', '17:00'];
const horasOcupadas = resultado.map(c => c.hora);
const horasDisponibles = horariosBase.filter(h => !horasOcupadas.includes(h));

return `Citas encontradas:\n${horariosOcupados}\n\nHorarios disponibles: ${horasDisponibles.join(', ') || 'Ninguno disponible'}`;

const staticData = $getWorkflowStaticData('global');
const citas = staticData.citas || [];
const queryStr = ($input.first().json.query || '').toLowerCase();

const index = citas.findIndex(c => {
  if (c.estado !== 'confirmada') return false;
  return (c.cliente && c.cliente.toLowerCase().includes(queryStr)) ||
         (c.id && c.id.toLowerCase().includes(queryStr));
});

if (index === -1) {
  return `No se encontro una cita activa para "${queryStr}". Verifica el nombre o ID.`;
}

const citaCancelada = citas[index];
citas[index].estado = 'cancelada';
citas[index].canceladaEn = new Date().toISOString();

return `Cita cancelada: Cliente: ${citaCancelada.cliente}, Servicio: ${citaCancelada.servicio}, Fecha: ${citaCancelada.fecha}, Hora: ${citaCancelada.hora}, Barbero: ${citaCancelada.barbero}`;

// Formatear y enviar respuesta por WhatsApp
const aiResponse = $input.first().json.output || $input.first().json.text || 'Lo siento, no pude procesar tu mensaje. Podrias intentar de nuevo?';

// Obtener datos del mensaje original
let phoneNumberId, from;
try {
  const originalData = $('Extraer Datos WhatsApp').first().json;
  phoneNumberId = originalData.phoneNumberId;
  from = originalData.from;
} catch(e) {
  phoneNumberId = null;
  from = null;
}

// WhatsApp tiene limite de 4096 chars por mensaje
let finalMessage = aiResponse;
if (finalMessage.length > 4000) {
  finalMessage = finalMessage.substring(0, 4000) + '\n\n... (mensaje recortado)';
}

return [{
  json: {
    phoneNumberId: phoneNumberId,
    to: from,
    text: finalMessage
  }
}];
